{
    /** 写入剪贴板文本；仅在宿主确认写入成功后完成。 */
    copyText(text: string): Promise<void>;
    /** 显示提示消息 */
    showMessage(message: string, type?: PageMessageType): void;
    /** 显示确认对话框，返回用户操作结果 */
    showConfirm(message: string, title?: string, options?: {
        confirmText?: string;
        cancelText?: string;
        type?: PageMessageType;
    }): Promise<boolean>;
    /** 显示输入弹窗 */
    showPrompt(message: string, title?: string, options?: {
        placeholder?: string;
        defaultValue?: string;
    }): Promise<string | null>;
    /** 显示提示框（无取消操作） */
    showAlert(message: string, title?: string, options?: {
        type?: PageMessageType;
    }): Promise<void>;
    /** 显示自定义对话框 */
    showDialog(options: PageDialogOptions): Promise<PageDialogResult>;
    /** 打开实体选择器 */
    selectEntities(options: PageSelectEntitiesOptions): Promise<PageSelectorOption[]>;
    /** 打开文件浏览对话框 */
    browseFiles(options?: PageBrowseFilesOptions): Promise<PageSelectedFile[]>;
    /**
     * 通过宿主文件传输能力上传文件。默认实现要求每个成功项返回非空 URL，传输失败或回执缺失时以 PageUploadError 拒绝并保留已确认/未确认文件；宿主覆盖可返回正式的非 URL 引用。
     * 字段组件随后仍通过原 DataView 字段写入该引用，上传服务本身不提交 DataSet。
     */
    uploadFiles(options: PageUploadFilesOptions): Promise<PageUploadedFile[]>;
    /** 显示 / 隐藏全局 Loading */
    showLoading(show: boolean, text?: string): void;
    /** 路由跳转 */
    navigate(path: string, params?: Record<string, unknown>): void;
}

